pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }
    function testRegression_property() public {
        address alice = address(0x1234);
        vm.deal(alice, 10 ether);
        vm.roll(1);
        vm.warp(1);
        vm.prank(alice);
        (bool success, ) = address(c).call{value: 10 ether}("");
        require(success, "call failed");
        address contractAddress = address(c);
        assertEq(contractAddress.balance, 10 ether);
    }
}
